function ensureContext(){if(state.server==='direct'){if(state.channel!=='notes'&&!state.conversations.some(c=>c.id===state.channel))state.channel='notes';}else{if(!Object.hasOwn(allServers(),state.server))state.server='afterhours';if(!server().channels.some(([id])=>id===state.channel))state.channel=server().channels[0]?.[0]||'general';}if(!Array.isArray(state.messages[key()]))state.messages[key()]=[];}
function toast(text){const n=$('toast');if(!n)return;n.textContent=text;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3600);}
function mergeMessages(other){const tombstones=new Set([...state.deleted,...other.deleted]);state.deleted=[...tombstones].slice(-2000);Object.entries(other.messages).forEach(([k,list])=>{const merged=new Map((state.messages[k]||[]).map(m=>[m.id,m]));list.forEach(m=>{const own=merged.get(m.id);if(!own||(m.updatedAt||m.time)>(own.updatedAt||own.time))merged.set(m.id,m);});state.messages[k]=[...merged.values()].filter(m=>!tombstones.has(m.id)).sort((a,b)=>a.time-b.time).slice(-500);});Object.keys(state.messages).forEach(k=>state.messages[k]=state.messages[k].filter(m=>!tombstones.has(m.id)));}
